Section RotLR.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  Ltac pxo PX := repeat (apply PIXat_out; [| rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; lia | rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn; lia]); exact PX.

  (* [comment removed for export] *)
  Lemma lr_A : forall regs m (s pix : Z) (v : pixv) (ret : word),
    (176 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pix)%Z -> PIXat m pix v -> (pix + 64 <= s - 176 \/ s <= pix)%Z -> p_d v = 1%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 176)) 176 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pix -> getr regs 11 = Z_to_bv 64 pix ->
    exists regs',
      msteps SEGS (mkst regs (0x88440 : word) m rom) (mkst regs' (0xfa23c : word) (MLR_A m s pix v ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 128) /\ getr regs' 1 = Z_to_bv 64 0x88510
      /\ getr regs' 10 = Z_to_bv 64 256 /\ getr regs' 11 = Z_to_bv 64 1
      /\ getr regs' 8 = Z_to_bv 64 (p_data v) /\ getr regs' 9 = Z_to_bv 64 pix /\ getr regs' 18 = Z_to_bv 64 (p_wpl v)
      /\ getr regs' 20 = Z_to_bv 64 pix /\ getr regs' 19 = getr regs 19
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 13; 14; 18; 19; 20]%list) regs regs'.
Proof.
