  (* [comment removed for export] *)
  Lemma lr_T1n : forall regs m (tab i : Z),
    (0 <= i)%Z -> (i + 1 < 256)%Z -> (0 <= tab)%Z -> (tab + 256 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (tab + i)) 1 = true ->
    getr regs 10 = Z_to_bv 64 i -> getr regs 11 = Z_to_bv 64 (2 * i) -> getr regs 12 = Z_to_bv 64 (8 * i) -> getr regs 13 = Z_to_bv 64 (32 * i) ->
    getr regs 14 = Z_to_bv 64 (128 * i) -> getr regs 15 = Z_to_bv 64 (tab + 256) -> getr regs 16 = Z_to_bv 64 (tab + i) ->
    exists regs' (bb : byte),
      msteps SEGS (mkst regs (0x88530 : word) m rom) (mkst regs' (0x88530 : word) (wbytes m (Z_to_bv 64 (tab + i)) [bb]) rom)
      /\ getr regs' 10 = Z_to_bv 64 (i + 1) /\ getr regs' 11 = Z_to_bv 64 (2 * (i + 1)) /\ getr regs' 12 = Z_to_bv 64 (8 * (i + 1))
      /\ getr regs' 13 = Z_to_bv 64 (32 * (i + 1)) /\ getr regs' 14 = Z_to_bv 64 (128 * (i + 1)) /\ getr regs' 16 = Z_to_bv 64 (tab + (i + 1))
      /\ regs_agree (fun r => In r [5; 6; 7; 10; 11; 12; 13; 14; 16; 17; 28; 29; 30]%list) regs regs'.
