  (* [comment removed for export] *)
  Lemma lr_T1x : forall regs m (tab i wpl : Z),
    (i = 255)%Z -> (0 <= tab)%Z -> (tab + 256 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (tab + i)) 1 = true ->
    getr regs 10 = Z_to_bv 64 i -> getr regs 11 = Z_to_bv 64 (2 * i) -> getr regs 12 = Z_to_bv 64 (8 * i) -> getr regs 13 = Z_to_bv 64 (32 * i) ->
    getr regs 14 = Z_to_bv 64 (128 * i) -> getr regs 15 = Z_to_bv 64 (tab + 256) -> getr regs 16 = Z_to_bv 64 (tab + i) ->
    getr regs 18 = Z_to_bv 64 wpl ->
    exists regs' (bb : byte),
      msteps SEGS (mkst regs (0x88530 : word) m rom) (mkst regs' (0xfa23c : word) (wbytes m (Z_to_bv 64 (tab + i)) [bb]) rom)
      /\ getr regs' 1 = Z_to_bv 64 0x88704 /\ getr regs' 10 = Z_to_bv 64 wpl /\ getr regs' 11 = Z_to_bv 64 4
      /\ regs_agree (fun r => In r [1; 5; 6; 7; 10; 11; 12; 13; 14; 16; 17; 28; 29; 30]%list) regs regs'.
