  (* [comment removed for export] *)
  Lemma lr_Bh : forall regs m (s w h wpl data buf : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= buf < 2 ^ 64)%Z -> (1 <= w < 2 ^ 31)%Z -> (1 <= h < 2 ^ 31)%Z -> (1 <= wpl < 2 ^ 29)%Z ->
    (w mod 32 <> 0)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 116)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 1)) ->
    rdn SEGS m (Z_to_bv 64 (s - 108)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) ->
    rdn SEGS m (Z_to_bv 64 (s - 112)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    rdn SEGS m (Z_to_bv 64 0x1f748) 4 = Some (Z_to_le_bytes 4 430068) ->
    getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 10 = Z_to_bv 64 buf -> getr regs 18 = Z_to_bv 64 wpl -> getr regs 8 = Z_to_bv 64 data ->
    exists regs',
      msteps SEGS (mkst regs (0x88704 : word) m rom) (mkst regs' (0x7cb48 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x8876c
      /\ getr regs' 10 = Z_to_bv 64 data /\ getr regs' 11 = Z_to_bv 64 h /\ getr regs' 12 = Z_to_bv 64 1 /\ getr regs' 13 = Z_to_bv 64 wpl
      /\ getr regs' 14 = Z_to_bv 64 0 /\ getr regs' 15 = Z_to_bv 64 h /\ getr regs' 16 = Z_to_bv 64 (32 - w mod 32)
      /\ getr regs' 19 = Z_to_bv 64 buf /\ getr regs' 20 = Z_to_bv 64 (4 * wpl) /\ getr regs' 21 = Z_to_bv 64 w
      /\ regs_agree (fun r => In r [1; 10; 11; 12; 13; 14; 15; 16; 19; 20; 21]%list) regs regs'.
