  (* [comment removed for export] *)
  Lemma lr_Bn : forall regs m (s w wpl buf : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= buf < 2 ^ 64)%Z -> (1 <= w < 2 ^ 31)%Z -> (1 <= wpl < 2 ^ 29)%Z ->
    (w mod 32 = 0)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 116)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 1)) ->
    rdn SEGS m (Z_to_bv 64 (s - 108)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) ->
    rdn SEGS m (Z_to_bv 64 0x1f748) 4 = Some (Z_to_le_bytes 4 430068) ->
    getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 10 = Z_to_bv 64 buf -> getr regs 18 = Z_to_bv 64 wpl ->
    exists regs',
      msteps SEGS (mkst regs (0x88704 : word) m rom) (mkst regs' (0x88770 : word) m rom)
      /\ getr regs' 19 = Z_to_bv 64 buf /\ getr regs' 20 = Z_to_bv 64 (4 * wpl) /\ getr regs' 21 = Z_to_bv 64 w
