  Lemma lr_C : forall regs m (s w : Z), (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= w < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 108)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) -> getr regs 2 = Z_to_bv 64 (s - 128) ->
