  (* [comment removed for export] *)
  Lemma lr_D : forall regs m (s w h wpl data : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= w < 2 ^ 30)%Z -> (1 <= h < 2 ^ 31)%Z -> (1 <= wpl < 2 ^ 29)%Z -> (w <= 32 * wpl)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 112)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 21 = Z_to_bv 64 w -> getr regs 20 = Z_to_bv 64 (4 * wpl) -> getr regs 18 = Z_to_bv 64 wpl ->
    getr regs 8 = Z_to_bv 64 data ->
    exists regs',
      msteps SEGS (mkst regs (0x88770 : word) m rom) (mkst regs' (0x887bc : word) m rom)
      /\ getr regs' 22 = Z_to_bv 64 0 /\ getr regs' 23 = Z_to_bv 64 (4 * wpl - 1) /\ getr regs' 24 = Z_to_bv 64 (4 * wpl)
      /\ getr regs' 25 = Z_to_bv 64 (4 * wpl - 1 - (w + 7) / 8) /\ getr regs' 26 = Z_to_bv 64 data
      /\ regs_agree (fun r => In r [10; 11; 22; 23; 24; 25; 26]%list) regs regs'.
Proof.
