  (* [comment removed for export] *)
  Lemma lr_H : forall regs m (wpl data buf i : Z),
    (0 <= i)%Z -> (1 <= wpl)%Z -> (0 <= data)%Z -> (data + 4 * wpl * i < 2 ^ 64)%Z ->
    getr regs 22 = Z_to_bv 64 i -> getr regs 18 = Z_to_bv 64 wpl -> getr regs 8 = Z_to_bv 64 data -> getr regs 19 = Z_to_bv 64 buf ->
    getr regs 20 = Z_to_bv 64 (4 * wpl) ->
    exists regs',
      msteps SEGS (mkst regs (0x887bc : word) m rom) (mkst regs' (0x109cb0 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x887d4 /\ getr regs' 10 = Z_to_bv 64 buf /\ getr regs' 11 = Z_to_bv 64 (data + 4 * wpl * i)
      /\ getr regs' 12 = Z_to_bv 64 (4 * wpl)
      /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs'.
