  (* [comment removed for export] *)
  Lemma lr_E1e : forall regs m (bpl buf tab line j db : Z) (b1 b2 : byte),
    (0 <= j)%Z -> (j + 1 = db)%Z -> (db <= bpl < 2 ^ 31)%Z -> (0 <= buf)%Z -> (buf + bpl < 2 ^ 64)%Z -> (0 <= tab)%Z -> (tab + 256 < 2 ^ 64)%Z ->
    (0 <= line)%Z -> (line + bpl < 2 ^ 64)%Z -> (0 <= flip3 (line + j) < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (flip3 (buf + (bpl - 1 - j)))) 1 = Some [b1] ->
    rdn SEGS m (Z_to_bv 64 (tab + u b1)) 1 = Some [b2] ->
    store_ok SEGS m (Z_to_bv 64 (flip3 (line + j))) 1 = true ->
    getr regs 19 = Z_to_bv 64 buf -> getr regs 9 = Z_to_bv 64 tab -> getr regs 10 = Z_to_bv 64 (line + j) -> getr regs 11 = Z_to_bv 64 (bpl - 1 - j) ->
    getr regs 25 = Z_to_bv 64 (bpl - 1 - db) ->
    exists regs' (bb : byte),
      msteps SEGS (mkst regs (0x887e0 : word) m rom) (mkst regs' (0x887ac : word) (wbytes m (Z_to_bv 64 (flip3 (line + j))) [bb]) rom)
      /\ regs_agree (fun r => In r [10; 11; 12; 13]%list) regs regs'.
Proof.
