  (* [comment removed for export] *)
  Lemma lr_Rx : forall regs m (s h i line wpl : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= i)%Z -> (i + 1 = h)%Z -> (h < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 112)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 22 = Z_to_bv 64 i -> getr regs 26 = Z_to_bv 64 line -> getr regs 24 = Z_to_bv 64 (4 * wpl) ->
    exists regs',
      msteps SEGS (mkst regs (0x887ac : word) m rom) (mkst regs' (0xfa374 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x88bb4 /\ getr regs' 10 = getr regs 19
      /\ regs_agree (fun r => In r [1; 10; 22; 26]%list) regs regs'.
