  (* [comment removed for export] *)
  Lemma lr_F : forall regs m (tab : Z), (1 <= tab < 2 ^ 64)%Z -> getr regs 9 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x88bb4 : word) m rom) (mkst regs' (0xfa374 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x88bc0 /\ getr regs' 10 = Z_to_bv 64 tab
      /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
