  (* [comment removed for export] *)
  Lemma lr_G : forall regs m (s : Z) (ret v8 v9 v18 v19 v20 v21 v22 v23 v24 v25 v26 pd : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret ->
    cellsZ m [(s - 8, ret); (s - 16, v8); (s - 24, v9); (s - 32, v18); (s - 40, v19); (s - 48, v20); (s - 56, v21); (s - 64, v22);
              (s - 72, v23); (s - 80, v24); (s - 88, v25); (s - 96, v26); (s - 104, pd)]%Z ->
    getr regs 2 = Z_to_bv 64 (s - 128) ->
    exists regs',
      msteps SEGS (mkst regs (0x88bc0 : word) m rom) (mkst regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = pd
      /\ getr regs' 8 = v8 /\ getr regs' 9 = v9 /\ getr regs' 18 = v18 /\ getr regs' 19 = v19 /\ getr regs' 20 = v20
      /\ getr regs' 21 = v21 /\ getr regs' 22 = v22 /\ getr regs' 23 = v23 /\ getr regs' 24 = v24 /\ getr regs' 25 = v25 /\ getr regs' 26 = v26
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 18; 19; 20; 21; 22; 23; 24; 25; 26]%list) regs regs'.
Proof.
